ALTER TABLE "mira_browser_consoles" DROP CONSTRAINT "mira_browser_console_state", ADD CONSTRAINT "mira_browser_console_state" CHECK (("state"='idle' AND "payload" IS NULL AND "method" IS NULL AND "expires_at" IS NULL) OR ("state" IN ('queued','claimed') AND "controller"='human' AND "command_id" IS NOT NULL AND "method" IN ('observe','navigate','act','upload','download') AND "expires_at" IS NOT NULL AND (("state"='queued' AND "payload" IS NOT NULL) OR ("state"='claimed' AND "payload" IS NULL))));